async fn supervisor_alive(directory : String) -> Bool {
  let lock = @fs.open(directory + "/supervisor.lock", mode=ReadWrite,
    create_mode=OpenOrCreate, permission=0o600)
  defer lock.close()
  !lock.try_lock(Exclusive)
}

///|
async fn ensure_supervisor() -> Unit {
  let directory = adapter_state_home()
  @fs.mkdir(directory, recursive=true, permission=0o700, allow_exist=true)
  let startup = @fs.open(directory + "/supervisor-startup.lock", mode=ReadWrite,
    create_mode=OpenOrCreate, permission=0o600)
  defer startup.close()
  @async.with_timeout(10000, async fn() {
    while !startup.try_lock(Exclusive) { @async.sleep(10) }
    if supervisor_alive(directory) { return }
    let sink = @process.redirect_to_file("/dev/null", shared=true)
    defer sink.close()
    ignore(@process.spawn_orphan(saved_proxy_executable(), ["--supervisor", directory],
      stdin=@process.redirect_from_file("/dev/null"), stdout=sink, stderr=sink))
    while !supervisor_alive(directory) { @async.sleep(10) }
  })
}

///|
pub async fn supervisor(directory : String) -> Unit {
  guard directory == adapter_state_home() else {
    raise AdapterError("Supervisor state directory mismatch")
  }
  let lock = @fs.open(directory + "/supervisor.lock", mode=ReadWrite,
    create_mode=OpenOrCreate, permission=0o600)
  defer lock.close()
  if !lock.try_lock(Exclusive) { return }
  @fs.write_file(directory + "/supervisor.pid", proxy_pid().to_string(), permission=0o600)
  defer (@fs.remove(directory + "/supervisor.pid") catch { _ => () })
  save_diagnostic("supervisor", "started", evidence={"stateDirectory": directory})
  defer save_diagnostic("supervisor", "stopped")
  let active : Map[String, Bool] = {}
  let transports : Map[String, Bool] = {}
  let mut idle_since = @env.now()
  @async.with_task_group(async fn(group) {
    while @fs.exists(directory) {
      let base = directory + "/tunnels"
      if @fs.exists(base) {
        for name in @fs.readdir(base) {
          let workspace = base + "/" + name
          if active.contains(workspace) || !@fs.exists(workspace + "/enabled") ||
            !@fs.exists(workspace + "/state.json") { continue }
          active.set(workspace, true)
          group.spawn_bg(no_wait=true, async fn() {
            defer active.remove(workspace)
            try {
              save_diagnostic("supervisor-workspace", "started", tunnel_directory=workspace)
              tunnel_worker(workspace)
              save_diagnostic("supervisor-workspace", "stopped", tunnel_directory=workspace)
            } catch {
              error => {
                save_diagnostic("supervisor-workspace", "failed", tunnel_directory=workspace,
                  error_type="workspace_task_failed", error_message=redact_credentials(error.to_string()))
                @async.sleep(1000)
              }
            }
          })
        }
      }
      let base = directory + "/transports"
      if @fs.exists(base) {
        for name in @fs.readdir(base) {
          let transport = base + "/" + name
          if transports.contains(transport) || !@fs.exists(transport + "/state.json") ||
            @fs.exists(transport + "/done") { continue }
          transports.set(transport, true)
          group.spawn_bg(no_wait=true, async fn() {
            defer transports.remove(transport)
            supervise_transport(transport) catch {
              error => save_diagnostic("supervisor-transport", "failed", error_type="transport_cleanup_failed",
                error_message=redact_credentials(error.to_string()))
            }
          })
        }
      }
      if !active.is_empty() || !transports.is_empty() {
        idle_since = @env.now()
      } else if @env.now() - idle_since >= 1000 {
        return
      }
      @async.sleep(100)
    }
  })
}

///|
async fn supervise_transport(directory : String) -> Unit {
  let state = @json.parse(@fs.read_file(directory + "/state.json").text())
  let pid = @string.parse_int(required(state, "pid"))
  guard pid > 1 else { raise AdapterError("Invalid transport owner") }
  let owner = @fs.open(directory + "/owner.lock", mode=ReadWrite)
  defer owner.close()
  save_diagnostic("supervisor-transport", "started", evidence={"pid": pid})
  while true {
    let abandoned = owner.try_lock(Exclusive)
    let exited = @fs.exists(directory + "/exited")
    let eof = if @fs.exists(directory + "/eof") {
      @env.now() >= @string.parse_uint64(@fs.read_file(directory + "/eof").text()) + 1000
    } else { false }
    if abandoned || exited || eof {
      if !exited {
        ignore(proxy_signal(-pid, 15))
        @async.sleep(500)
      }
      ignore(proxy_signal(-pid, 9))
      save_diagnostic("supervisor-transport", "stopped", evidence={"pid": pid,
        "reason": if abandoned { "owner_exited" } else if exited { "transport_exited" } else { "stdin_eof" }})
      @fs.write_file(directory + "/done", "", permission=0o600)
      if abandoned { @fs.rmdir(directory, recursive=true) }
      return
    }
    @async.sleep(100)
  }
}
